CREATE TABLE IF NOT EXISTS fake_runs(id TEXT PRIMARY KEY, state TEXT NOT NULL, result TEXT, operation TEXT NOT NULL UNIQUE, pid INTEGER, session TEXT NOT NULL, cwd TEXT NOT NULL, executable TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS supervisor_requests(id TEXT PRIMARY KEY, command TEXT NOT NULL, response TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS supervisor_events(sequence INTEGER PRIMARY KEY AUTOINCREMENT, run TEXT NOT NULL, payload TEXT NOT NULL);
